const input = $input.first().json || {};
// Log enough to find the failed run, and nothing that looks like a secret.
const summary = {
  workflow: input.workflow?.name || input.workflow?.id || 'unknown',
  executionId: input.execution?.id || input.executionId || null,
  node: input.execution?.lastNodeExecuted || input.node?.name || null,
  message: input.execution?.error?.message || input.error?.message || 'Workflow failed',
  at: new Date().toISOString(),
};
console.error('[LendLoop] workflow error', summary);
return [{ json: summary }];
